import type { Clima, Pergunta } from "@/features/metricas/eventos";

export type Humor = Clima["humor"];
export type Experiencia = Clima["experiencia"];
export type Companhia = Clima["companhia"];

/**
 * As telas do wizard, na ordem, com o parâmetro de cada resposta na URL.
 * Os rótulos das respostas estão em `ROTULOS_CLIMA` (`src/features/metricas/rotulos.ts`).
 */
export const PERGUNTAS = [
  { chave: "humor", parametro: "humor", titulo: "Como você está se sentindo?" },
  { chave: "experiencia", parametro: "exp", titulo: "Que tipo de experiência você quer?" },
  { chave: "companhia", parametro: "com", titulo: "Com quem vai assistir?" },
] as const satisfies { chave: Pergunta; parametro: string; titulo: string }[];

/** Trechos do motivo: "Você está cansado, quer rir e vai ver a dois". */
export const TRECHOS: { [P in Pergunta]: Record<Clima[P], string> } = {
  humor: {
    cansado: "Você está cansado",
    animado: "Você está animado",
    "pra-baixo": "Você está pra baixo",
    nostalgico: "Você está nostálgico",
    ansioso: "Você está ansioso",
    "de-boa": "Você está de boa",
  },
  experiencia: {
    rir: "quer rir",
    emocionar: "quer se emocionar",
    susto: "quer levar um susto",
    tenso: "quer ficar tenso",
    pensar: "quer pensar",
    distrair: "quer só se distrair",
  },
  companhia: {
    sozinho: "vai ver sozinho",
    "a-dois": "vai ver a dois",
    familia: "vai ver com as crianças",
    amigos: "vai ver com os amigos",
  },
};
=== recomendar
import type { Clima } from "@/features/metricas/eventos";
import type { EstadoNoite } from "@/features/noite/estado";
import { filtrosDaNoite } from "@/features/noite/filtros";
import { motivoDaNoite, provedorDaNoite } from "@/features/noite/motivo";
import type { PreferenciasInput } from "@/features/preferencias/schema";
import type { ApiFilmes } from "@/lib/tmdb/filmes";
import type {
  FilmeDetalhes,
  FilmeResumo,
  FiltrosDescoberta,
  Pagina,
  Provedor,
} from "@/lib/tmdb/tipos";

export type ApiNoite = Pick<ApiFilmes, "descobrirFilmes" | "obterFilme">;
export type PerfilNoite = Pick<PreferenciasInput, "generosEvitados" | "streamings">;

export type FilmeDaNoite = { filme: FilmeDetalhes; provedor: Provedor | null; motivo: string };
export type ResultadoNoite = { destaque: FilmeDaNoite; opcoes: FilmeDaNoite[] };

type Entrada = {
  respostas: Clima;
  estado: Pick<EstadoNoite, "tom" | "duracaoMax" | "vistos" | "trocas">;
  perfil: PerfilNoite;
  /** "Já assisti" e filmes com reação. */
  excluir: number[];
  api: ApiNoite;
};

/** Páginas lidas por consulta para completar a rodada. */
const PAGINAS_POR_CONSULTA = 2;

async function consultar(api: ApiNoite, filtros: FiltrosDescoberta): Promise<Pagina<FilmeResumo>> {
  try {
    return await api.descobrirFilmes(filtros);
  } catch (erro) {
    console.error("[noite] consulta falhou:", erro);
    return { itens: [], pagina: 1, totalPaginas: 0, totalResultados: 0 };
  }
}

async function detalhar(api: ApiNoite, id: number): Promise<FilmeDetalhes | null> {
  try {
    return await api.obterFilme(id);
  } catch (erro) {
    console.error("[noite] detalhes falharam:", erro);
    return null;
  }
}

/**
 * Filmes da rodada: 1 na primeira, 1 destaque + 2 opções depois de uma troca.
 * Busca primeiro nos streamings da pessoa e completa sem filtro de provedor. Nunca devolve
 * filme excluído, já mostrado ou de gênero evitado. `null` quando não sobra nenhum.
 */
export async function recomendarNoite({
  respostas,
  estado,
  perfil,
  excluir,
  api,
}: Entrada): Promise<ResultadoNoite | null> {
  const evitados = perfil.generosEvitados;
  const { tom, duracaoMax } = estado;
  const noite = filtrosDaNoite({ respostas, tom, duracaoMax }, evitados);
  if (!noite) return null;

  const quantidade = estado.trocas === 0 ? 1 : 3;
  const bloqueados = new Set([...excluir, ...estado.vistos]);
  const escolhidos: FilmeResumo[] = [];
  const consultas: FiltrosDescoberta[] = perfil.streamings.length
    ? [{ ...noite.filtros, provedores: perfil.streamings }, noite.filtros]
    : [noite.filtros];

  for (const filtros of consultas) {
    for (let pagina = 1; pagina <= PAGINAS_POR_CONSULTA; pagina++) {
      if (escolhidos.length >= quantidade) break;
      const resultado = await consultar(api, { ...filtros, pagina });
      for (const filme of resultado.itens) {
        const evitado = filme.generos.some((genero) => evitados.includes(genero));
        if (escolhidos.length >= quantidade || evitado || bloqueados.has(filme.id)) continue;
        escolhidos.push(filme);
        bloqueados.add(filme.id);
      }
      if (pagina >= resultado.totalPaginas) break;
    }
  }

  const detalhes = await Promise.all(escolhidos.map(({ id }) => detalhar(api, id)));
  const [destaque, ...opcoes] = detalhes
    .filter((filme): filme is FilmeDetalhes => filme !== null)
    .map((filme) => {
      const provedor = provedorDaNoite(filme.ondeAssistir, perfil.streamings);
      return { filme, provedor, motivo: motivoDaNoite(respostas, noite.tom, filme, provedor) };
    });
  return destaque ? { destaque, opcoes } : null;
}
=== termina
/**
 * "23h40": hora em que o filme termina se começar em `inicio`, no fuso de quem chama.
 * Use no navegador, para valer o fuso da pessoa (o servidor roda em UTC).
 */
export function terminaAs(inicio: Date, duracaoMin: number): string {
  const fim = new Date(inicio.getTime() + duracaoMin * 60_000);
  return `${fim.getHours()}h${String(fim.getMinutes()).padStart(2, "0")}`;
}
=== motivo
import type { Clima } from "@/features/metricas/eventos";
import type { Tom } from "@/features/noite/mapeamento";
import { TRECHOS } from "@/features/noite/opcoes";
import type { OndeAssistir, Provedor } from "@/lib/tmdb/tipos";

/** "na Netflix", "no Globoplay": artigo de cada streaming da lista do onboarding, pelo ID. */
const ARTIGOS: Record<number, "na" | "no"> = {
  8: "na",
  119: "no",
  337: "no",
  1899: "na",
  307: "no",
  350: "na",
  531: "no",
  283: "na",
  11: "no",
};

const nota = new Intl.NumberFormat("pt-BR", { minimumFractionDigits: 1, maximumFractionDigits: 1 });

/** O streaming por assinatura a citar: um dos da pessoa, se houver; senão, o primeiro. */
export function provedorDaNoite(
  onde: OndeAssistir | null,
  streamings: readonly number[],
): Provedor | null {
  const assinatura = onde?.assinatura ?? [];
  return assinatura.find(({ id }) => streamings.includes(id)) ?? assinatura[0] ?? null;
}

function ondeVer(provedor: Provedor | null): string {
  if (!provedor) return "não está nos seus streamings";
  return `está ${ARTIGOS[provedor.id] ?? "em"} ${provedor.nome}`;
}

/**
 * "Você está cansado, quer rir e vai ver a dois: comédia leve, nota 7,8, está na Netflix."
 * Só usa as respostas, o tom da rodada e o filme; nunca os gêneros favoritos.
 */
export function motivoDaNoite(
  respostas: Clima,
  tom: Tom,
  filme: { nota: number },
  provedor: Provedor | null,
): string {
  const humor = TRECHOS.humor[respostas.humor];
  const experiencia = TRECHOS.experiencia[respostas.experiencia];
  const companhia = TRECHOS.companhia[respostas.companhia];
  const filmeDaNoite = `${tom.nome}, nota ${nota.format(filme.nota)}, ${ondeVer(provedor)}`;
  return `${humor}, ${experiencia} e ${companhia}: ${filmeDaNoite}.`;
}
=== filtros
import type { Clima } from "@/features/metricas/eventos";
import {
  AJUSTES_COMPANHIA,
  AJUSTES_HUMOR,
  ORDEM_PADRAO,
  PISO,
  TONS,
  type Tom,
} from "@/features/noite/mapeamento";
import type { FiltrosDescoberta } from "@/lib/tmdb/tipos";

export type RodadaNoite = {
  respostas: Clima;
  /** Índice do tom ("Não é o clima" avança). */
  tom: number;
  /** Limite de duração vindo de "Muito longo", se houver. */
  duracaoMax: number | null;
};

export type FiltrosNoite = { filtros: FiltrosDescoberta; tom: Tom };

/**
 * Filtros do TMDB para a rodada (tabelas de `SPEC/2026-11-18-wizard-noite.md`).
 * A experiência escolhe o tom; o humor e a companhia ajustam; os gêneros evitados do perfil
 * são absolutos, e os favoritos não entram. `null` se todos os tons tiverem gênero evitado.
 */
export function filtrosDaNoite(rodada: RodadaNoite, evitados: number[]): FiltrosNoite | null {
  const { respostas, tom, duracaoMax } = rodada;
  const experiencia = TONS[respostas.experiencia];
  const disponiveis = experiencia.tons.filter((t) => !t.generos.some((g) => evitados.includes(g)));
  const escolhido = disponiveis[tom % disponiveis.length];
  if (!escolhido) return null;

  const humor = AJUSTES_HUMOR[respostas.humor];
  const companhia = AJUSTES_COMPANHIA[respostas.companhia];
  // A experiência manda mais que o humor: o humor não exclui o gênero do tom.
  const semDoHumor = (humor.sem ?? []).filter((g) => !escolhido.generos.includes(g));
  const semGeneros = [...new Set([...evitados, ...(experiencia.sem ?? []), ...semDoHumor])];
  const limites = [humor.duracaoMax, duracaoMax ?? undefined].filter((n) => n !== undefined);

  return {
    tom: escolhido,
    filtros: {
      todosGeneros: escolhido.generos,
      ...(semGeneros.length > 0 && { semGeneros }),
      ...(limites.length > 0 && { duracaoMax: Math.min(...limites) }),
      ...(humor.lancadoAte && { lancadoAte: humor.lancadoAte }),
      ...(companhia.classificacaoMax && { classificacaoMax: companhia.classificacaoMax }),
      notaMin: PISO.notaMin,
      votosMin: PISO.votosMin,
      ordem: humor.ordem ?? companhia.ordem ?? ORDEM_PADRAO,
    },
  };
}

import type { Evento } from "@/features/metricas/eventos";

export const ROTA_EVENTOS = "/api/eventos";

/**
 * Registra um evento a partir do navegador, sem esperar resposta e sem lançar erro.
 * `sendBeacon` sobrevive ao fechamento da página (necessário para `wizard_abandonado`);
 * o corpo é uma string, então vai como `text/plain` e não precisa de preflight.
 */
export function enviarEvento(evento: Evento): void {
  try {
    const corpo = JSON.stringify(evento);
    if (typeof navigator.sendBeacon === "function" && navigator.sendBeacon(ROTA_EVENTOS, corpo)) {
      return;
    }
    fetch(ROTA_EVENTOS, { method: "POST", body: corpo, keepalive: true }).catch(() => {});
  } catch {
    // Métrica nunca quebra a tela.
  }
}
import { z } from "zod";

/** Limite de trocas do wizard (pedido do cliente, 3.2). */
export const MAX_TROCAS = 5;

export const MOTIVOS_TROCA = ["ja-vi", "nao-e-o-clima", "muito-longo", "outro"] as const;
export const RESPOSTAS_COMO_FOI = ["amei", "gostei", "nao-gostei", "nao-vi"] as const;
export const ORIGENS_TRAILER = ["filme", "noite"] as const;
export const ETAPAS_WIZARD = ["perguntas", "resultado"] as const;

export type OrigemTrailer = (typeof ORIGENS_TRAILER)[number];

const semDados = z.strictObject({}).default({});

/**
 * Lista fechada de eventos e os dados de cada um (SPEC/2026-11-18-metricas.md).
 * Objetos estritos: qualquer chave a mais, como o clima do wizard, é recusada.
 */
export const eventoSchema = z.discriminatedUnion("nome", [
  z.object({ nome: z.literal("wizard_iniciado"), dados: semDados }),
  z.object({ nome: z.literal("wizard_concluido"), dados: semDados }),
  z.object({
    nome: z.literal("wizard_troca"),
    dados: z.strictObject({ motivo: z.enum(MOTIVOS_TROCA) }),
  }),
  z.object({
    nome: z.literal("wizard_escolheu"),
    dados: z.strictObject({ trocas: z.number().int().min(0).max(MAX_TROCAS) }),
  }),
  z.object({
    nome: z.literal("wizard_abandonado"),
    dados: z.strictObject({ etapa: z.enum(ETAPAS_WIZARD) }),
  }),
  z.object({ nome: z.literal("como_foi_exibido"), dados: semDados }),
  z.object({
    nome: z.literal("como_foi_respondido"),
    dados: z.strictObject({ resposta: z.enum(RESPOSTAS_COMO_FOI) }),
  }),
  z.object({
    nome: z.literal("trailer_aberto"),
    dados: z.strictObject({ origem: z.enum(ORIGENS_TRAILER) }),
  }),
]);

/** Evento como quem registra escreve (`dados` pode faltar nos eventos sem dados). */
export type Evento = z.input<typeof eventoSchema>;
export type NomeEvento = Evento["nome"];

/** Respostas do wizard contadas sem vínculo com a pessoa. */
export const CLIMAS = {
  humor: ["cansado", "animado", "pra-baixo", "nostalgico", "ansioso", "de-boa"],
  experiencia: ["rir", "emocionar", "susto", "tenso", "pensar", "distrair"],
  companhia: ["sozinho", "a-dois", "familia", "amigos"],
} as const;

export type Pergunta = keyof typeof CLIMAS;

export const climaSchema = z.object({
  humor: z.enum(CLIMAS.humor),
  experiencia: z.enum(CLIMAS.experiencia),
  companhia: z.enum(CLIMAS.companhia),
});

export type Clima = z.infer<typeof climaSchema>;
import type { NomeEvento, Pergunta } from "@/features/metricas/eventos";

/** Ordem e descrição dos eventos na página de métricas. */
export const ROTULOS_EVENTO: Record<NomeEvento, string> = {
  wizard_iniciado: "Abriu o wizard",
  wizard_concluido: "Chegou à recomendação",
  wizard_troca: "Pediu outra sugestão",
  wizard_escolheu: "Clicou “Vou ver esse!”",
  wizard_abandonado: "Saiu sem escolher",
