import { createServer } from "node:http";

const PORTA = Number(process.argv[2] ?? process.env.TMDB_FALSO_PORTA ?? 4010);
const GENERO_QUE_FALHA = "99"; // Documentário: sempre 503, para testar seção com erro.

const NOMES = {
  28: "Ação",
  16: "Animação",
